<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableValueAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVariableValueAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateVariableValueAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getValue returns null on a freshly created holder.
     */
    public function testValueNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVariableValueAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isValueAssigned());
        $this->assertNull($holder->getValue());
    }
}
class ImplWithTemplateVariableValueAttributeHolderUnitTest
{
    use TemplateVariableValueAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedValueRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultValue();
    }
}
